-- ============================================================================
-- OSG — HORAS e VOLUMES mapeados (modelo de VOLUME: volume_executions = nº de
-- execuções/ano). Acompanha o refactor do roiCalculator: execucoesAnuais() usa
-- processes.volume_executions (frequency virou fallback legado).
-- Modelo: 20 PROJETOS/ano; horas por etapa = esforço POR PROJETO (multiplicidade
-- de matrículas/ACs embutida nas horas). volume_per_process fica em 1.
-- ROI: anual = Σ_etapa(horas × volume_per_process[=1]) × volume_executions[=20].
-- Origem: _osg_planilha/horas_maximizadas.json. Escopo: SOMENTE cluster OSG.
-- ============================================================================
BEGIN;
DO $$ DECLARE v_osg uuid := '0523512c-f980-4236-8a7c-53e06c9c7a80'; n int;
BEGIN
  SELECT count(*) INTO n FROM public.processes WHERE cluster_id=v_osg; IF n<>34 THEN RAISE EXCEPTION 'esperados 34 processos OSG, há %',n; END IF;
  SELECT count(*) INTO n FROM public.process_stages WHERE scenario='AS-IS' AND process_id IN (SELECT id FROM public.processes WHERE cluster_id=v_osg); IF n<>155 THEN RAISE EXCEPTION 'esperadas 155 etapas AS-IS OSG, há %',n; END IF;
END $$;

